#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int main() {
    ifstream plik("ciag.txt");
    vector<int> dane;
    int x;
    while (plik >> x) dane.push_back(x);
    int maxLen = 1, maxStart = 0;
    int curLen = 1, curStart = 0;
    for (int i = 1; i < (int)dane.size(); i++) {
        if (dane[i] > dane[i - 1]) {
            curLen++;
        } else {
            if (curLen > maxLen) {
                maxLen = curLen;
                maxStart = curStart;
            }
            curLen = 1;
            curStart = i;
        }
    }
    if (curLen > maxLen) {
        maxLen = curLen;
        maxStart = curStart;
    }
    cout << "Najdluzszy ciag rosnacy: " << maxLen << " elementow" << endl;
    cout << "Poczatek: pozycja " << maxStart + 1 << endl;
    cout << "Elementy:";
    for (int i = maxStart; i < maxStart + maxLen; i++) {
        cout << " " << dane[i];
    }
    cout << endl;
    return 0;
}
```

Weryfikacja:
- Ciagi rosnace: (3,5,7) dl=3, (2,4,8,12) dl=4, (1,9,11,14) dl=4
- Najdluzszy pierwszy: (2,4,8,12) od pozycji 4, dlugosc 4
